PRAGMA foreign_keys = ON;
CREATE TABLE knowledge (id TEXT PRIMARY KEY, title TEXT NOT NULL, content TEXT NOT NULL, normalized_title TEXT NOT NULL UNIQUE, understanding INTEGER NOT NULL CHECK(understanding BETWEEN 0 AND 3), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE knowledge_categories (knowledge_id TEXT PRIMARY KEY REFERENCES knowledge(id), category_id TEXT NOT NULL REFERENCES categories(id));
CREATE TABLE tags (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE knowledge_tags (knowledge_id TEXT NOT NULL REFERENCES knowledge(id), tag_id TEXT NOT NULL REFERENCES tags(id), PRIMARY KEY(knowledge_id,tag_id));
CREATE TABLE sources (id TEXT PRIMARY KEY, knowledge_id TEXT NOT NULL UNIQUE REFERENCES knowledge(id), url TEXT NOT NULL UNIQUE);
CREATE TABLE quizzes (id TEXT PRIMARY KEY, knowledge_id TEXT NOT NULL REFERENCES knowledge(id), type TEXT NOT NULL CHECK(type IN ('recall','choice')), prompt TEXT NOT NULL, answer TEXT NOT NULL, explanation TEXT NOT NULL, options_json TEXT NOT NULL, correct_index INTEGER, active INTEGER NOT NULL CHECK(active IN (0,1)), CHECK((type='recall' AND correct_index IS NULL) OR (type='choice' AND correct_index BETWEEN 0 AND 2)));
CREATE TABLE reviews (id TEXT PRIMARY KEY, knowledge_id TEXT NOT NULL REFERENCES knowledge(id), quiz_id TEXT NOT NULL REFERENCES quizzes(id), rating TEXT NOT NULL CHECK(rating IN ('forgot','unsure','remembered')), response TEXT NOT NULL, selected_index INTEGER, correct INTEGER CHECK(correct IN (0,1)), idempotency_key TEXT NOT NULL UNIQUE, request_json TEXT NOT NULL, schedule_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE review_state (knowledge_id TEXT PRIMARY KEY REFERENCES knowledge(id), due_at TEXT NOT NULL, interval_days REAL NOT NULL CHECK(interval_days>=0 AND interval_days<=180), streak INTEGER NOT NULL CHECK(streak>=0), lapses INTEGER NOT NULL CHECK(lapses>=0), reviews INTEGER NOT NULL CHECK(reviews>=0), status TEXT NOT NULL CHECK(status IN ('new','learning','mastered')), version INTEGER NOT NULL CHECK(version>=0));
CREATE TABLE notes (id TEXT PRIMARY KEY, knowledge_id TEXT NOT NULL UNIQUE REFERENCES knowledge(id), content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX knowledge_updated ON knowledge(updated_at);
CREATE INDEX knowledge_archive ON knowledge(archived_at);
CREATE INDEX review_due ON review_state(due_at);
CREATE INDEX quizzes_knowledge ON quizzes(knowledge_id,active);
CREATE INDEX reviews_knowledge ON reviews(knowledge_id,created_at);
CREATE INDEX reviews_created ON reviews(created_at);
CREATE INDEX knowledge_category_lookup ON knowledge_categories(category_id);
CREATE INDEX knowledge_tag_lookup ON knowledge_tags(tag_id);
